@Bean
ItemProcessor<RegistroCpesec, CpeMonterrey> cpesecADetalle(P310Properties props) {
    return r -> {
        if (r.tipo() == 1 || r.tipo() == 99) return null;
        if (r.tipo() != 2) {
            log.error("ERROR; TIPREG DET INVALIDO {}", r.tipo());
            if (props.abortarTipoInvalido()) throw new ProcesoAbortadoException("TIPREG " + r.tipo());
            return null;                              // comportamiento actual: DMTERMINATE comentado
        }
        return CpeMonterrey.desde(r);                 // DuplicateKey = INVALID KEY -> aborta
    };
}

/**
 * SAT-DETALLE: 150 posiciones, grupo de 10 dígitos sin separador y el resto separado por comas.
 * Los importes llevan punto decimal implícito: no es un CSV estándar.
 */
@Component
class SaldosSatLineAggregator implements LineAggregator<CuentaCpe> {

    @Override
    public String aggregate(CuentaCpe c) {
        String cuerpo = String.join(",",
                "2" + "%010d".formatted(c.grupo()),                    // TIPOREG + AREA..GPO = B39-GRUPO
                "%04d".formatted(c.subGrupo()),                        // SAT-CTE
                "%04d".formatted(c.sucursalMda()),                     // primeros 4 de B39-NUM-MDA
                "%08d".formatted(c.cuentaMda()),                       // últimos 8
                Implicito.de(c.saldoPromedio(), 16, 2),                // 9(16)V99
                Implicito.de(c.tasaNeta152(), 2, 3),                   // 9(02)V999
                Implicito.de(c.rendimientoPagado152(), 12, 2),         // 9(12)V99
                "%02d".formatted(c.opcionGrupo()),                     // B37-OPCION
                "%04d".formatted(c.rangoGrupo()),                      // B37-RANGO
                c.periodo());                                          // AAAAMM
        return cuerpo + " ".repeat(6);                                 // FILLER X(06)
    }
}

final class Implicito {
    /** Formatea sin punto, truncando como MOVE a un PIC más corto (RoundingMode.DOWN). */
    static String de(BigDecimal v, int enteros, int decimales) {
        BigDecimal t = v.setScale(decimales, RoundingMode.DOWN);
        return ("%0" + (enteros + decimales) + "d").formatted(t.unscaledValue());
    }
}

@Component
@StepScope
@RequiredArgsConstructor
public class CuentaCpeProcessor implements ItemProcessor<CuentaCpe, CuentaCpe> {

    private final ContratoCaptacionRepository b03;
    private final HistoricoRepository b06;
    private final CpeMonterreyRepository cpeind;
    private final CalculoRendimientoCpe calculo;     // 230-ACTUALIZA-B39-VDM / -MTY
    private final P310Properties props;

    @Override
    public CuentaCpe process(CuentaCpe b39) {
        return switch (b39.numCsi()) {
            case 4 -> cpeind.findById(b39.contrato())
                    .map(m -> calculo.desdeMonterrey(b39, m))
                    .orElseGet(() -> b39.excluir());                          // STATUS 4
            case 10 -> b03.findForUpdate(b39.contrato())
                    .filter(c -> c.getNumProducto() == 1 && c.getNumInstrum() == 3)   // MTDP-2466
                    .filter(c -> !props.statusBeneficiarioArt61().contains(c.getStaBenef()))  // 3 y 8
                    .flatMap(c -> b06.findForUpdate(c.getNumContrato()).map(h -> calculo.desdeVdm(b39, c, h)))
                    .orElseGet(() -> b39.excluir());
            default -> null;                                                   // otros CSI: no se tocan
        };
    }
}

// Corte por B39-GRUPO (el lector va ordenado por B39SXGPOSBGMDA): CorteGrupoListener, en s11.
// afterWrite: al cambiar de grupo, si hubo cuentas activas, STORE B37 y reinicia TODOS los acumulados,
//             incluidos los cheques girados que el fuente no reinicia.
// afterStep:  cierra el último grupo, que el ciclo del fuente nunca alcanza.

@Component
@RequiredArgsConstructor
class CalculoRendimientoCpe {

    private final FactoresIsr.Factores isr;
    private final ComisionCpe comisiones;            // 240-L422-COMXCTA
    private final GrupoCpeRepository b37;
    private final P310Properties props;

    CuentaCpe desdeVdm(CuentaCpe b39, ContratoCaptacion b03, Historico b06) {
        boolean extranjero = props.tiposPersonaExtranjero().contains(b03.getTipoPersona());  // 11, 12, 15
        b39.setTasaIsr500(extranjero ? isr.extranjero() : isr.estandar());

        b39.setChequesGirados(b06.getContComis(50));        // subíndice 50 compilado
        b39.setDiasCiclo(b06.getDiasCiclo());
        b39.setSaldoPromedio(b06.getPromCiclo(12));          // subíndice 12 compilado
        b39.setTipoPersona(b03.getTipoPersona());
        b39.setNombre(b03.getNombre());
        b39.setStatus(b03.getStatus());
        comisiones.aplica(b39, b03.getNumContrato());

        if (props.opcionesConRendimiento().contains(b37.opcion(b39.grupo()))) {   // 1, 2, 5
            b39.setTasaNeta500(b03.getTasaAnterior());
            b39.setRendPag500(b03.getIntsCapit());
            b39.setIsrRet500(b03.getImpuestoRet());
            b39.setTasaBruta500(b06.getTasaBruta());
        } else {
            b39.limpiaRendimientos500();                     // MOVE ZEROS
        }
        return b39;
    }
}

@Component
@RequiredArgsConstructor
class CuentaCpeWriter implements ItemWriter<CuentaCpe> {

    private final CuentaCpeRepository b39;
    private final IvaPorSucursal iva;                // 42000080-DATOS-S080 + S080IVA
    private final AcumuladoGrupo acum;

    /** 235-STORE-B39. El chunk es la transacción; equivale a BEGIN/END-TRANSACTION NO-AUDIT. */
    @Override
    @Transactional
    public void write(Chunk<? extends CuentaCpe> chunk) {
        for (CuentaCpe c : chunk) {
            c.setCveIva(iva.esFronteriza(c.sucProm()) ? iva.claveFrontera() : iva.claveGeneral());
            if (c.getStatus() == 0 || c.getStatus() == 1) acum.sumaCuentaActiva();
            b39.save(c);
        }
    }
}

@Component
@RequiredArgsConstructor
class ComisionCpe {
    private final ComisionesL422Client l422;         // S016 L422, sistema 500, paso 310
    private final P310Properties props;

    void aplica(CuentaCpe b39, String contrato) {
        l422.comisionPorCuenta(500, 310, 1, 3, contrato)
            .map(r -> r.concepto(props.conceptoL422()))   // índice (04)
            .ifPresentOrElse(
                k -> { b39.setUsoFut01(k.claveCobro()); b39.setTariChqGir(k.comision()); },
                () -> { b39.setUsoFut01(props.cobroPorOmision());          // 2
                        b39.setTariChqGir(props.comisionPorOmision()); });  // 100
    }
}
// Auditoría: el fuente usa END-TRANSACTION NO-AUDIT; en JPA se desactiva Envers/auditoría
// para esta entidad y se registra el resultado del job en el JobRepository.

@Component
@RequiredArgsConstructor
class CorteGrupoListener implements ItemWriteListener<CuentaCpe>, StepExecutionListener {

    private final GrupoCpeRepository b37;
    private final AcumuladoGrupo acum;

    /**
     * 300-TERMINA vuelve a ejecutar 200-ACTUALIZA-CUENTAS desde el inicio de B39 para que el
     * primer cambio de grupo de ese segundo recorrido guarde el último grupo del primero.
     * En Java basta con cerrar el grupo abierto al terminar el step: una sola pasada.
     */
    @Override
    @Transactional
    public ExitStatus afterStep(StepExecution se) {
        if (acum.grupoAbierto() && acum.cuentasActivas() > 0) {
            b37.actualiza(acum.grupo(), acum.saldoPromedio(), acum.rendimientos(), acum.chequesGirados());
        }
        acum.reinicia();
        return se.getExitStatus();
    }
}
